p.deleted_at IS NULL

    AND p.outlet_id IN (SELECT id FROM outlet WHERE vendor_id = #{q.vendorId} AND deleted_at IS NULL)


    AND p.outlet_id = #{q.outletId}


    AND (
        p.name LIKE CONCAT('%', #{q.name}, '%')
        OR EXISTS (
            SELECT 1 FROM product_barcode pb
            WHERE pb.product_id = p.id AND pb.code LIKE CONCAT('%', #{q.name}, '%')
        )
        OR EXISTS (
            SELECT 1 FROM product_supplier psk
            WHERE psk.product_id = p.id
              AND psk.code IS NOT NULL
              AND psk.code LIKE CONCAT('%', #{q.name}, '%')
        )
        OR p.region LIKE CONCAT('%', #{q.name}, '%')
        OR p.vintage LIKE CONCAT('%', #{q.name}, '%')
    )


    AND p.category_id = #{q.categoryId}


    AND p.brand_id IN

        #{bid}



    AND p.brand_id = #{q.brandId}


    AND p.brand_id IS NULL


    AND (p.brand_id IS NULL OR p.brand_id != #{q.excludeBrandId})


    AND p.family_id = #{q.familyId}


    AND p.status IN

        #{s}



    AND p.status = #{q.status}


    AND p.type = #{q.type}


    AND EXISTS (SELECT 1 FROM product_tag pt
                WHERE pt.product_id = p.id AND pt.tag_id = #{q.tagId})


    AND p.tax_rate_id IN

        #{tid}



    AND p.tax_rate_id = #{q.taxRateId}


    AND p.cost_tax_rate_id IN

        #{tid}



    AND p.cost_tax_rate_id = #{q.costTaxRateId}


    AND EXISTS (SELECT 1 FROM product_supplier ps
                WHERE ps.product_id = p.id AND ps.supplier_id = #{q.supplierId})


    AND NOT EXISTS (SELECT 1 FROM product_supplier ps
                    WHERE ps.product_id = p.id AND ps.supplier_id = #{q.excludeSupplierId})


    AND p.type = 'INTEGRATED'


    AND (p.type IS NULL OR p.type <> 'INTEGRATED')



    AND COALESCE(inv.total_qty, 0) > 0


    AND COALESCE(inv.total_qty, 0) <> 0


    AND inv.product_id IS NOT NULL AND COALESCE(inv.total_qty, 0) = 0


    AND inv.product_id IS NULL

mapper.update:
UPDATE product
SET name = #{p.name}, status = #{p.status}, description = #{p.description},
    category_id = #{p.categoryId}, brand_id = #{p.brandId}, family_id = #{p.familyId},
    tax_rate_id = #{p.taxRateId}, cost_tax_rate_id = #{p.costTaxRateId},
    cost = #{p.cost},
    case_cost = CASE WHEN cost IS DISTINCT FROM #{p.cost} OR case_quantity IS DISTINCT FROM #{p.caseQuantity}
                          OR cost_percentage IS DISTINCT FROM #{p.costPercentage}
                     THEN NULL ELSE case_cost END,
    shopfront_catalog_confirmed = CASE WHEN cost IS DISTINCT FROM #{p.cost} OR case_quantity IS DISTINCT FROM #{p.caseQuantity}
                                            OR cost_percentage IS DISTINCT FROM #{p.costPercentage}
                                       THEN FALSE ELSE shopfront_catalog_confirmed END,
    case_quantity = #{p.caseQuantity},
    cost_percentage = #{p.costPercentage},
    prevent_manual_discounts = #{p.preventManualDiscounts},
    request_price = #{p.requestPrice}, request_quantity = #{p.requestQuantity},
    track_inventory = #{p.trackInventory}, show_shortcuts = #{p.showShortcuts},
    abv = #{p.abv}, volume_ml = #{p.volumeMl},
    region = #{p.region}, vintage = #{p.vintage}, image = #{p.image}
WHERE id = #{p.id}

