INSERT INTO product_supplier (product_id, supplier_id, outlet_id) SELECT p.id, s.id, p.outlet_id FROM product p JOIN outlet po ON po.id=p.outlet_id AND po.vendor_id=#{vendorId} AND po.deleted_at IS NULL JOIN supplier s ON s.id=#{supplierId} AND s.deleted_at IS NULL JOIN outlet so ON so.id=s.outlet_id AND so.vendor_id=#{vendorId} AND so.deleted_at IS NULL WHERE p.id IN
#{id}
AND p.deleted_at IS NULL AND NOT EXISTS ( SELECT 1 FROM product_supplier ps WHERE ps.product_id=p.id AND ps.supplier_id=s.id AND ps.outlet_id=p.outlet_id )
